head.script:
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getDomById('grid1_groupbyFilterBox_select')
}
scwin.setVal1 = function() {
    return rowHeight = WebSquare.wUnit.getDomById($p.id + 'grid1_groupbyFilterBox_select_itemTable_2').getBoundingClientRect().height;
}
scwin.setVal2 = function() {
    return selectHeight = WebSquare.wUnit.getDomById($p.id + 'grid1_groupbyFilterBox_select_itemTable').getBoundingClientRect().height;
}
scwin.checkVal1 = function() {
    return rowHeight * 3 > selectHeight && rowHeight * 2 <= selectHeight;
}
scwin.checkVal2 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'grid1_groupbyFilterBox_select_itemTable')).getPropertyValue('overflow-x') == 'hidden';
}
scwin.checkVal3 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'grid1_groupbyFilterBox_select_itemTable')).getPropertyValue('overflow-y') == 'auto';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 filterBoxvisibleRowNum 부분을 확인한다.
    //1. In the Source tab, check the filterBoxvisibleRowNum part.
    //Verify step 1. filterBoxvisibleRowNum='2'
    //1. filterBoxvisibleRowNum='2'
    //Test step 2. groupbyFilterBox 부분을 확인한다.
    //2. Check the groupbyFilterBox part.
    //Verify step 2. groupbyFilterBox='true'
    //2. groupbyFilterBox='true'
    //Test step 3. groupbyFilterBoxLocation 부분을 확인한다.
    //3. Check the groupbyFilterBoxLocation part.
    //Verify step 3. groupbyFilterBoxLocation='top' (top / bottom 택일)
    //3. groupbyFilterBoxLocation='top' (top / bottom 택일)
    //Test step 4. 브라우저에서 run 버튼을 클릭한다.
    //4. Click the run button in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 4. 상단에 filterBox 가 생성된다.
    //4. A filterBox is created at the top.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    //WebSquare.wUnit.addCommand("assert", "typeof grid1_groupbyFilterBox_select", "object");
    //Test step 5. 생성된 filterBox 의 위치를 확인한다.
    //5. Check the location of the generated filterBox.
    //Verify step 5. 3번에서 설정한 위치에 filterBox 가 표시된다.
    //5. The filterBox is displayed at the position set in step 3.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1_groupbyFilterBox_select').getBoundingClientRect().top < 50", "true");
    //Test step 6. filterBox 에 category1 / category2 / category3 를 이용해서 필터 또는 사용자필터를 3~4개 생성한다. (코멘트 참고)
    //6. Create three or four filters or user filters using category1 / category2 / category3 in the filterBox. (See comment)
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[0].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_groupbyZone_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[0].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[1].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_groupbyZone_list_listColumn_checkbox')[3].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[1].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[2].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_groupbyZone_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column_labelDiv')[2].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_groupbyFilterBox_select_main_tbody').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 6. filterBox 리스트가 추가된다.
    //6. The filterBox list is added.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1_groupbyFilterBox_select_label').innerText", "(category3 = NULL)");
    //Test step 7. filterBox 리스트를 확인한다.
    //7. Check the filterBox list.
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    //Verify step 7. row 의 개수가 2줄만 표현되며 스크롤이 생성된다.
    //7. The number of rows is represented by only two lines and scrolling is generated.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.arr = [];
    for (window.i = 0; i < 50000; i++) {
        for (window.j = 0; j < 7; j++) {
            arr.push(Math.floor((Math.random() * (100 - 1 + 1)) + 1));
        }
    }
    /*
    window.arr = [];
    arr.push( 1 );
    arr.push( 2 );
    arr.push( 3 );
    arr.push( 4 );
    arr.push( 5 );
    arr.push( 6 );
    arr.push( 7 );
    arr.push( 8 );
    arr.push( 9 );
    arr.push( 10 );
    arr.push( 11 );
    arr.push( 12 );
    arr.push( 13 );
    arr.push( 14 );
    */
    dataList1.setData(arr);
    input1.setValue(" [ 0, 1, 2] ");
    input2.setValue(" [ 1, 0, 1] ");
    input3.setValue(" { inputType:'expression', expression: 'toggle()+depthStr()+\"    [ \"+count()+\" 건 ]\"', align: 'left', colSpan:9} ");
    input4.setValue("");
    input5.setValue("");
    input6.setValue(" {colSpan:7} ");
    input7.setValue(" {hidden:true} ");
    input8.setValue(' {"category1":["1","2","3"], "category2":["1","2","3"]} ');
    input9.setValue(" [ {value:'합계'}, {inputType:'expression', expression:'SUM(\"category7\")'} ] ");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 21-Feb-2018
    window.rowHeight = 0;
    window.selectHeight = 0;
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

xf:trigger.script:
var sortOrder = (input1.getValue().length!=0?input1.getValue():"[]");
var sortIndex = (input2.getValue().length!=0?input2.getValue():"[]");
var rowNumHeader = (input3.getValue().length!=0?input3.getValue():"{}");
var rowStatusHeader = (input4.getValue().length!=0?input4.getValue():"{}");
var groupbyHeader = (input5.getValue().length!=0?input5.getValue():"[]");
var rowNumFooter = (input6.getValue().length!=0?input6.getValue():"{}");
var rowStatusFooter = (input7.getValue().length!=0?input7.getValue():"{}");
var filter = (input8.getValue().length!=0?input8.getValue():"{}");
var groupbyFooter = (input9.getValue().length!=0?input9.getValue():"[]");

var groupbyFunctionStr = textbox1.getValue();
var groupbyFunctionArr = groupbyFunctionStr.replaceAll("&nbsp;","").replaceAll("<br>","").replaceAll('"',"'").split(":");
var dm = ":";

groupbyFunctionStr =
	groupbyFunctionArr[0] + dm + sortOrder +
	groupbyFunctionArr[1] + dm + sortIndex +
	groupbyFunctionArr[2] + dm + rowNumHeader +
	groupbyFunctionArr[3] + dm + rowStatusHeader +
	groupbyFunctionArr[4] + dm + groupbyHeader +
	groupbyFunctionArr[5] + dm + rowNumFooter +
	groupbyFunctionArr[6] + dm + rowStatusFooter +
	groupbyFunctionArr[7] + dm + filter +
	groupbyFunctionArr[8] + dm + groupbyFooter +
	groupbyFunctionArr[9];
	eval(groupbyFunctionStr);

var infoArr = [];
var options = {};
var infoObj = {};

// 엑셀 다운로드 기본 옵션 설정
options.fileName         = "excel.xlsx";
options.type             =  "1";
options.startRowIndex    = 0;
options.startColumnIndex = 0;
//options.headerColor      = "#DBEEF3";
//options.footerColor      = "#92CDDC";
options.groupby = "true";
options.useFooter = true;
options.headerColor = "#123455";

grid1.advancedExcelDownload(options, infoArr);
